def digest(raw):
    return sha256(raw).hexdigest()


def require(condition, reason):
    if not condition:
        raise RuntimeError('HOLD_WOW_RELAY_' + reason)


def trusted_read(path, limit):
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC)
    with os.fdopen(fd, 'rb') as handle:
        info = os.fstat(handle.fileno())
        require(stat.S_ISREG(info.st_mode) and info.st_uid == 0 and info.st_nlink == 1
                and info.st_mode & 0o077 == 0 and 0 < info.st_size <= limit, 'KEY_SCOPE')
        return handle.read(limit)


def bundle():
    require(os.geteuid() == 0 and re.fullmatch('[1-9][0-9]{0,19}',
            os.environ.get('NOX_OWNER_REQUEST_ID', '')), 'OWNER')
    for folder in (KEYS, *KEYS.parents):
        mode = folder.lstat()
        require(stat.S_ISDIR(mode.st_mode) and mode.st_uid == 0 and mode.st_mode & 0o022 == 0,
                'DIRECTORY_SCOPE')
    cert = KEYS / 'ingress.pem'
    key = KEYS / 'ingress.key'
    require(digest(trusted_read(cert, 3000)) == CERT_SHA, 'RECIPIENT_PIN')
    trusted_read(key, 6000)
    cipher = base64.b64decode(CIPHER, validate=True)
    require(len(cipher) <= 200000 and digest(cipher) == CIPHER_SHA, 'CIPHER_PIN')
    result = subprocess.run(
        ('/usr/bin/openssl', 'cms', '-decrypt', '-binary', '-inform', 'DER',
         '-recip', str(cert), '-inkey', str(key)), input=cipher, stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL, timeout=8, check=False,
    )
    require(result.returncode == 0 and digest(result.stdout) == BUNDLE_SHA, 'BUNDLE_PIN')
    return gzip.decompress(result.stdout)



