def main():
    edge = bundle()
    require(len(edge) == 121145 and digest(edge) == '58f7343a6cb6178ddb188a16b50f7a276e4cf3a1cfe93b20cb7d07ddd4c87c1a', 'EDGE_ASSET_PIN')
    stages = (('EDGE', edge), ('DIALOG', CHECK))
    results = {}
    for label, source in stages:
        try:
            exec(compile(source, 'nox_' + label.lower() + '.py', 'exec'),
                 {'__name__': '__main__', '__file__': 'nox_' + label.lower() + '.py'})
            results[label] = True
        except SystemExit as error:
            results[label] = error.code in (None, 0)
        except Exception as error:
            reason = str(error)
            reason = reason if re.fullmatch(r'HOLD_[A-Z0-9_]{1,120}', reason) else type(error).__name__
            print('NOX_MAINT_WOW_FINAL_' + label + '_HOLD=' + reason, flush=True)
            results[label] = False
    print('NOX_MAINT_WOW_FINAL=' + json.dumps(results, separators=(',', ':')), flush=True)
    if not all(results.values()):
        raise SystemExit(2)
    print('NOX_MAINT_REPAIR_COMPLETE=true', flush=True)

if __name__ == '__main__':
    main()
